import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { FEATURE_NAMES, type FeatureName, buildFeatures, cellSizeM } from "./features.js";
import { RasterGrid } from "./raster-grid.js";

// Generated by the Python implementation (ml/urbanheat_ml/golden.py). If this fails, the TypeScript port and
// ml/urbanheat_ml/features.py disagree: fix the port (or, after an intentional spec change, port it and regenerate).
interface Golden {
  width: number;
  height: number;
  res_lon: number;
  res_lat: number;
  lat_center: number;
  cell_dx_m: number;
  cell_dy_m: number;
  inputs: Record<"canopy" | "impervious" | "elevation", (number | null)[]>;
  water: number[];
  features: Record<FeatureName, (number | null)[]>;
}
const golden = JSON.parse(readFileSync(fileURLToPath(new URL("../test-fixtures/features-golden.json", import.meta.url)), "utf8")) as Golden;
const grid = (v: (number | null)[]) => new RasterGrid(Float32Array.from(v, (x) => (x === null ? NaN : x)), golden.width, golden.height, [0, 0, 1, 1]);

test("cell size matches the Python computation", () => {
  const s = cellSizeM(golden.res_lon, golden.res_lat, golden.lat_center);
  assert.ok(Math.abs(s.dxM - golden.cell_dx_m) < 1e-9, `${s.dxM} vs ${golden.cell_dx_m}`);
  assert.ok(Math.abs(s.dyM - golden.cell_dy_m) < 1e-9);
});

test("every feature matches the Python output on the golden scene (NaN pattern included)", () => {
  const size = cellSizeM(golden.res_lon, golden.res_lat, golden.lat_center);
  const f = buildFeatures({ canopy: grid(golden.inputs.canopy), impervious: grid(golden.inputs.impervious), elevation: grid(golden.inputs.elevation), water: golden.water }, size);
  assert.deepEqual([...f.names], [...FEATURE_NAMES]);
  let compared = 0;
  let nanCells = 0;
  for (const name of FEATURE_NAMES) {
    const exp = golden.features[name];
    const got = f.data[name];
    assert.equal(got.length, exp.length, name);
    for (let i = 0; i < exp.length; i++) {
      const e = exp[i];
      if (e === null) {
        assert.ok(Number.isNaN(got[i]!), `${name}[${i}] should be NaN, got ${got[i]}`);
        nanCells++;
      } else {
        const tol = 1e-9 * Math.max(1, Math.abs(e));
        assert.ok(Math.abs(got[i]! - e) <= tol, `${name}[${i}]: ts ${got[i]} vs python ${e}`);
        compared++;
      }
    }
  }
  assert.ok(compared > 8000, `only ${compared} values compared`);
  assert.ok(nanCells > 0, "the scene must include NaN features so the NaN pattern is checked too");
});
